/* @lc app=leetcode id=3815 lang=kotlin */ class AuctionSystem(val bids: HashMap<Long, Int> = HashMap(), val sets: HashMap<Int, java.util.TreeSet<Long>> = HashMap()) { fun addBid(userId: Int, itemId: Int, bidAmount: Int) { bids.put(userId * 100000L + itemId, bidAmount)?.let { old -> sets[itemId]!!.remove((old.toLong() shl 20) or userId.toLong()) }.let { sets.getOrPut(itemId) { java.util.TreeSet() }.add((bidAmount.toLong() shl 20) or userId.toLong()) } } fun updateBid(userId: Int, itemId: Int, newAmount: Int) { addBid(userId, itemId, newAmount) } fun removeBid(userId: Int, itemId: Int) { bids.remove(userId * 100000L + itemId)?.let { old -> sets[itemId]!!.remove((old.toLong() shl 20) or userId.toLong()) } } fun getHighestBidder(itemId: Int): Int = sets[itemId]?.let { if (it.isEmpty()) -1 else (it.last() and 0xFFFFF).toInt() } ?: -1 }